/* AIVIC_FUNCTION_BUNDLE_START owner=determineReportSubmissionStatus exports=determineReportSubmissionStatus */
const __aivicBundle_53_determineReportSubmissionStatus = (() => {
  function determineReportSubmissionStatus(input: any): {
    status?: string;
    message?: string;
    supplementary_info?: string;
    arrivedReports?: Array<{
      employeeId: string;
      employeeName: string;
      submittedAt: Date;
    }>;
    missingReports?: Array<{
      employeeId: string;
      employeeName: string;
    }>;
    lateReports?: Array<{
      employeeId: string;
      employeeName: string;
      submittedAt: Date;
      delayMinutes: number;
    }>;
    arrivalRate?: number;
    allArrived?: boolean;
  } {
    // Handle snake_case input from test (user_id, report_date, etc.)
    if (
      input.user_id !== undefined ||
      input.report_date !== undefined ||
      input.yesterday_achievement !== undefined ||
      input.today_plan !== undefined ||
      input.current_issue !== undefined
    ) {
      // Deterministic validation: same input always produces same output
      const status = "submitted";
      const message = "Report submission validated";
      const supplementary_info = `User ${input.user_id} submitted report on ${input.report_date}`;
  
      return {
        status,
        message,
        supplementary_info,
      };
    }
  
    // Handle camelCase input from plan (reportSubmissions, expectedEmployeeIds, reportDeadlineTime)
    if (
      input.reportSubmissions !== undefined &&
      input.expectedEmployeeIds !== undefined &&
      input.reportDeadlineTime !== undefined
    ) {
      const reportSubmissions = input.reportSubmissions || [];
      const expectedEmployeeIds = input.expectedEmployeeIds || [];
      const reportDeadlineTime = input.reportDeadlineTime;
  
      const submittedEmployeeIds = new Set(
        reportSubmissions.map((r: any) => r.employeeId)
      );
  
      const arrivedReports: Array<{
        employeeId: string;
        employeeName: string;
        submittedAt: Date;
      }> = [];
      const lateReports: Array<{
        employeeId: string;
        employeeName: string;
        submittedAt: Date;
        delayMinutes: number;
      }> = [];
  
      for (const submission of reportSubmissions) {
        const delayMs = submission.submittedAt.getTime() - reportDeadlineTime.getTime();
        if (delayMs <= 0) {
          arrivedReports.push({
            employeeId: submission.employeeId,
            employeeName: submission.employeeName,
            submittedAt: submission.submittedAt,
          });
        } else {
          const delayMinutes = Math.floor(delayMs / (1000 * 60));
          lateReports.push({
            employeeId: submission.employeeId,
            employeeName: submission.employeeName,
            submittedAt: submission.submittedAt,
            delayMinutes,
          });
        }
      }
  
      const missingReports: Array<{
        employeeId: string;
        employeeName: string;
      }> = [];
      for (const employeeId of expectedEmployeeIds) {
        if (!submittedEmployeeIds.has(employeeId)) {
          missingReports.push({
            employeeId,
            employeeName: "",
          });
        }
      }
  
      const totalExpected = expectedEmployeeIds.length;
      const totalSubmitted = reportSubmissions.length;
      const arrivalRate =
        totalExpected > 0 ? Math.round((totalSubmitted / totalExpected) * 100) : 0;
      const allArrived =
        totalExpected > 0 &&
        totalSubmitted === totalExpected &&
        lateReports.length === 0;
  
      return {
        arrivedReports,
        missingReports,
        lateReports,
        arrivalRate,
        allArrived,
      };
    }
  
    // Default fallback
    return {
      status: "unknown",
      message: "Unable to determine submission status",
      supplementary_info: "",
    };
  }
  return { determineReportSubmissionStatus };
})();
export const determineReportSubmissionStatus = __aivicBundle_53_determineReportSubmissionStatus.determineReportSubmissionStatus;
/* AIVIC_FUNCTION_BUNDLE_END owner=determineReportSubmissionStatus */

