const __aivicBundle_67_determineReportDelay = (() => {
  function determineReportDelay(reportData: {
    reportSubmissionTime: Date;
    morningMeetingStartTime: Date;
    employeeId?: string;
  }): {
    isOnTime: boolean;
    delayMinutes: number;
    status: string;
    isDelayed?: boolean;
  } {
    const submissionTime = reportData.reportSubmissionTime.getTime();
    const meetingTime = reportData.morningMeetingStartTime.getTime();
    const timeDifferenceMs = submissionTime - meetingTime;
    const delayMinutes = Math.max(0, Math.ceil(timeDifferenceMs / (1000 * 60)));
  
    const isOnTime = submissionTime <= meetingTime;
    const isDelayed = !isOnTime;
  
    let status: string;
    if (isOnTime) {
      status = '時間内';
    } else {
      status = '遅延';
    }
  
    return {
      isOnTime,
      delayMinutes,
      status,
      isDelayed,
    };
  }
  return { determineReportDelay };
})();
