const __aivicBundle_79_prioritizeReminderTargets = (() => {
  function prioritizeReminderTargets(
    employeeIdList: string[],
    reportDeadlineTimestamp: number,
    employeeReportStatus: Array<{
      employee_id: string;
      has_submitted: boolean;
      submitted_at_timestamp: number | null;
    }>
  ): Array<{
    employee_id: string;
    priority: number;
    status: 'not_submitted' | 'delayed';
    reason: string;
  }> {
    const statusMap = new Map(
      employeeReportStatus.map((item) => [item.employee_id, item])
    );
  
    const notSubmittedTargets: Array<{
      employee_id: string;
      priority: number;
      status: 'not_submitted' | 'delayed';
      reason: string;
    }> = [];
  
    const delayedTargets: Array<{
      employee_id: string;
      priority: number;
      status: 'not_submitted' | 'delayed';
      reason: string;
    }> = [];
  
    for (const employeeId of employeeIdList) {
      const status = statusMap.get(employeeId);
      if (!status) {
        continue;
      }
  
      if (!status.has_submitted) {
        notSubmittedTargets.push({
          employee_id: employeeId,
          priority: notSubmittedTargets.length + 1,
          status: 'not_submitted',
          reason: 'Report not yet submitted',
        });
      } else if (
        status.submitted_at_timestamp !== null &&
        status.submitted_at_timestamp > reportDeadlineTimestamp
      ) {
        delayedTargets.push({
          employee_id: employeeId,
          priority: delayedTargets.length + 1,
          status: 'delayed',
          reason: 'Report submitted after deadline',
        });
      }
    }
  
    const result = [
      ...notSubmittedTargets.map((item, index) => ({
        ...item,
        priority: index + 1,
      })),
      ...delayedTargets.map((item, index) => ({
        ...item,
        priority: notSubmittedTargets.length + index + 1,
      })),
    ];
  
    return result;
  }
  return { prioritizeReminderTargets };
})();
