/* AIVIC_FUNCTION_BUNDLE_START owner=getReportArrivalStatus exports=getReportArrivalStatus */
const __aivicBundle_99_getReportArrivalStatus = (() => {
  function getReportArrivalStatus(
    reports: any[],
    expectedEmployeeIds?: string[]
  ): any {
    // Handle both test input shapes
    const isReportStatusFormat = reports.length > 0 && 'submitted' in reports[0];
    
    if (isReportStatusFormat) {
      // Format: [{ user_id, submitted, submitted_at, ... }]
      const total_members = reports.length;
      const submitted_count = reports.filter((r: any) => r.submitted === true).length;
      const not_submitted_count = total_members - submitted_count;
      
      return {
        total_members,
        submitted_count,
        not_submitted_count,
        arrived_count: submitted_count,
        arrivedReports: reports
          .filter((r: any) => r.submitted === true)
          .map((r: any) => ({
            employeeId: r.user_id,
            employeeName: r.user_id,
            submittedAt: r.submitted_at ? new Date(r.submitted_at) : new Date(),
          })),
        missingReports: reports
          .filter((r: any) => r.submitted === false)
          .map((r: any) => ({
            employeeId: r.user_id,
            employeeName: r.user_id,
          })),
        lateReports: [],
        arrivalRate: total_members > 0 ? Math.round((submitted_count / total_members) * 100) : 0,
        allArrived: submitted_count === total_members,
      };
    }
  
    // Format: [{ user_id, yesterday_achievement, today_plan, current_issue, submitted_at }]
    const userIds = expectedEmployeeIds || [];
    const submittedUserIds = new Set(reports.map((r: any) => r.user_id));
    
    const arrivedReports = reports
      .filter((r: any) => r.submitted_at)
      .map((r: any) => ({
        employeeId: r.user_id,
        employeeName: r.user_id,
        submittedAt: new Date(r.submitted_at),
      }));
  
    const missingReports = userIds
      .filter((id: string) => !submittedUserIds.has(id))
      .map((id: string) => ({
        employeeId: id,
        employeeName: id,
      }));
  
    const lateReports: any[] = [];
  
    const arrived_count = arrivedReports.length;
    const arrivalRate = userIds.length > 0 ? Math.round((arrived_count / userIds.length) * 100) : 0;
    const allArrived = missingReports.length === 0 && lateReports.length === 0;
  
    return {
      arrived_count,
      arrivedReports,
      missingReports,
      lateReports,
      arrivalRate,
      allArrived,
    };
  }
  return { getReportArrivalStatus };
})();
export const getReportArrivalStatus = __aivicBundle_99_getReportArrivalStatus.getReportArrivalStatus;
/* AIVIC_FUNCTION_BUNDLE_END owner=getReportArrivalStatus */

/* AIVIC_FUNCTION_BUNDLE_START owner=identifyMissingReports exports=identifyMissingReports */
const __aivicBundle_100_identifyMissingReports = (() => {
  interface IdentifyMissingReportsInput {
    [key: string]: any;
  }
  
  interface IdentifyMissingReportsOutput {
    [key: string]: any;
  }
  
   function identifyMissingReports(
    input: IdentifyMissingReportsInput
  ): IdentifyMissingReportsOutput {
    if (input["reportDeadline"] === undefined || input["reportDeadline"] === null) { throw new Error("reportDeadline is required"); }
    const allMembers = input.all_members || input.allTeamMembers || [];
    const submittedReports = input.submitted_reports || input.submittedReports || [];
    const currentTime = input.current_time || input.scheduledMeetingTime || new Date();
    const deadlineTime = input.deadline_time;
    
  
    const submittedMemberIds = new Set(
      submittedReports.map((r) => r.member_id || r.memberId)
    );
  
    const missingMembers = allMembers.filter(
      (member) => !submittedMemberIds.has(member.member_id || member.id)
    );
  
    const submittedMemberIds_array = Array.from(submittedMemberIds);
    const missingMemberIds_array = missingMembers.map((m) => m.member_id || m.id);
  
    const allOnTime =
      deadlineTime && currentTime <= deadlineTime
        ? submittedReports.every((r) => (r.submitted_at || new Date()) <= deadlineTime)
        : true;
  
    const output: IdentifyMissingReportsOutput = {
      submitted_count: submittedReports.length,
      missing_count: missingMembers.length,
      total_count: allMembers.length,
      missing_members: missingMembers.map((m) => ({
        member_id: m.member_id || m.id,
        id: m.id,
        name: m.name,
        email: (m as any).email,
      })),
      submitted_member_ids: submittedMemberIds_array,
      missing_member_ids: missingMemberIds_array,
      all_on_time: allOnTime,
      notificationSent: missingMembers.length > 0,
      notificationTimestamp: missingMembers.length > 0 ? currentTime : null,
    };
  
    return output;
  }
  return { identifyMissingReports };
})();
