/* AIVIC_FUNCTION_BUNDLE_START owner=getDelayedReporters exports=getDelayedReporters */
const __aivicBundle_102_getDelayedReporters = (() => {
  function getDelayedReporters(
    reportSubmissions: any[],
    now: Date,
    reportDeadline: Date,
  ): any[] {
    const delayedReporters: any[] = [];
  
    for (const submission of reportSubmissions) {
      const submittedAt = submission.report_submitted_at;
      
      // If report_submitted_at is null, it means not submitted
      if (submittedAt === null || submittedAt === undefined) {
        const userId = submission.user_id || submission.employeeId;
        const userName = submission.user_name || submission.employeeName;
        
        delayedReporters.push({
          user_id: userId,
          user_name: userName,
          employeeId: userId,
          employeeName: userName,
          status: 'not_submitted',
          delayMinutes: Math.floor(
            (reportDeadline.getTime() - now.getTime()) / (1000 * 60)
          ),
        });
      } else if (submittedAt > reportDeadline) {
        // If submitted after deadline, calculate delay
        const delayMs = submittedAt.getTime() - reportDeadline.getTime();
        const delayMinutes = Math.floor(delayMs / (1000 * 60));
        
        const userId = submission.user_id || submission.employeeId;
        const userName = submission.user_name || submission.employeeName;
        
        delayedReporters.push({
          user_id: userId,
          user_name: userName,
          employeeId: userId,
          employeeName: userName,
          status: 'delayed',
          delayMinutes: delayMinutes,
        });
      }
    }
  
    return delayedReporters;
  }
  return { getDelayedReporters };
})();
export const getDelayedReporters = __aivicBundle_102_getDelayedReporters.getDelayedReporters;
/* AIVIC_FUNCTION_BUNDLE_END owner=getDelayedReporters */

/* AIVIC_FUNCTION_BUNDLE_START owner=classifyReportArrivalStatus exports=classifyReportArrivalStatus */
const __aivicBundle_103_classifyReportArrivalStatus = (() => {
  function classifyReportArrivalStatus(
    reportSubmissions: Array<{
      user_id?: string;
      employeeId?: string;
      submitted_at?: Date | null;
      submittedAt?: Date | null;
    }>,
    reportDeadlineTime: Date
  ): ReportArrivalStatusResult {
    const arrivedReports: Array<{
      employeeId: string;
      employeeName: string;
      submittedAt: Date;
    }> = [];
    const missingReports: Array<{
      employeeId: string;
      employeeName: string;
    }> = [];
    const lateReports: Array<{
      employeeId: string;
      employeeName: string;
      submittedAt: Date;
    }> = [];
  
    const arrived: Array<{
      user_id: string;
    }> = [];
    const not_arrived: Array<{
      user_id: string;
    }> = [];
    const delayed: Array<{
      user_id: string;
    }> = [];
  
    for (const submission of reportSubmissions) {
      const userId = submission.user_id || submission.employeeId || "";
      const submittedAt = submission.submitted_at || submission.submittedAt;
  
      if (submittedAt === null || submittedAt === undefined) {
        missingReports.push({
          employeeId: userId,
          employeeName: "",
        });
        not_arrived.push({
          user_id: userId,
        });
      } else {
        const submittedDate = new Date(submittedAt);
        if (submittedDate <= reportDeadlineTime) {
          arrivedReports.push({
            employeeId: userId,
            employeeName: "",
            submittedAt: submittedDate,
          });
          arrived.push({
            user_id: userId,
          });
        } else {
          lateReports.push({
            employeeId: userId,
            employeeName: "",
            submittedAt: submittedDate,
          });
          delayed.push({
            user_id: userId,
          });
        }
      }
    }
  
    const totalExpected = reportSubmissions.length;
    const totalArrived = arrivedReports.length;
    const arrivalRate =
      totalExpected > 0 ? Math.round((totalArrived / totalExpected) * 100) : 0;
    const allArrived = missingReports.length === 0 && lateReports.length === 0;
  
    return {
      arrivedReports,
      missingReports,
      lateReports,
      arrivalRate,
      allArrived,
      arrived,
      not_arrived,
      delayed,
    };
  }
  return { classifyReportArrivalStatus };
})();
