/* AIVIC_FUNCTION_BUNDLE_START owner=generateUnreportedPromptNotification exports=generateUnreportedPromptNotification */
const __aivicBundle_108_generateUnreportedPromptNotification = (() => {
  function generateUnreportedPromptNotification(input: any): any {
    const executionDate = input.execution_date || input.scheduledMeetingTime || new Date();
    const adminEmail = input.admin_email || input.managerEmail;
    const unreportedMembers = input.unreported_members || input.missingMembers || [];
  
    // Normalize unreported members to consistent format
    const normalizedMembers = unreportedMembers.map((member: any) => ({
      member_id: member.id || member.member_id,
      member_name: member.name || member.member_name,
      email: member.email,
    }));
  
    // Generate prompt message
    const executionHour = executionDate.getHours();
    const executionMinute = executionDate.getMinutes();
    const timeStr = `${String(executionHour).padStart(2, '0')}:${String(executionMinute).padStart(2, '0')}`;
  
    let promptMessage: string;
    if (normalizedMembers.length === 1) {
      promptMessage = `本日${timeStr}現在、以下の部員から朝会報告が未提出です。${normalizedMembers[0].member_name}`;
    } else {
      const memberNames = normalizedMembers.map((m: any) => m.member_name).join('、');
      promptMessage = `本日${timeStr}現在、以下の部員から朝会報告が未提出です。${memberNames}`;
    }
  
    // Build recipients list
    const recipients: Array<{ email: string; role: 'employee' | 'manager' }> = [];
  
    // Add employee recipients
    normalizedMembers.forEach((member: any) => {
      if (member.email) {
        recipients.push({
          email: member.email,
          role: 'employee',
        });
      }
    });
  
    // Add manager recipient
    if (adminEmail) {
      recipients.push({
        email: adminEmail,
        role: 'manager',
      });
    }
  
    // Determine priority and escalation
    const shouldEscalate = normalizedMembers.length > 1;
    const priority = shouldEscalate ? 'high' : 'high';
  
    // Return format compatible with both test and plan
    return {
      notificationMessage: promptMessage,
      prompt_message: promptMessage,
      recipients,
      priority,
      shouldEscalate,
      unreported_members_list: normalizedMembers,
    };
  }
  return { generateUnreportedPromptNotification };
})();
export const generateUnreportedPromptNotification = __aivicBundle_108_generateUnreportedPromptNotification.generateUnreportedPromptNotification;
/* AIVIC_FUNCTION_BUNDLE_END owner=generateUnreportedPromptNotification */

